"""Trusted TD-v1.3 development evaluator; never import in numeric workers.

The controller supplies complete planned case/bin rosters, immutable worker
outputs and evaluator-only scenario/tau data. This module does not load data,
fit forecasting models, select final cases, or perform any I/O. Missing cases
must be explicit records; missing predictions on fixed eligible IDs are errors.
"""
from __future__ import annotations

import math
from collections import defaultdict
from fractions import Fraction
from typing import Callable, Mapping, Sequence

import numpy as np


ARMS = ("G", "L", "ALL")
LAMBDA_PRIORITY = (1.0, 10.0, 0.1)
Q_REGISTRY = (0.95, 0.975, 0.99)
RANK_METRICS = ("rr", "hit1", "hit3", "hit5", "ndcg5")
REGISTERED_FOLDS = (
    (("ts-auth-service", "cpu"), ("ts-order-service", "disk")),
    (("ts-auth-service", "delay"), ("ts-travel-service", "loss")),
    (("ts-train-service", "cpu"), ("ts-route-service", "mem")),
    (("ts-train-service", "delay"), ("ts-travel-service", "disk")),
    (("ts-order-service", "loss"), ("ts-route-service", "socket")),
)


class EvaluationError(ValueError):
    """Malformed evidence or an invalid numerical configuration; do not drop it."""


class CoverageError(EvaluationError):
    """A declared development calibration/eligibility gate did not pass."""


def _ids(records: Mapping, planned_ids: Sequence) -> tuple:
    ids = tuple(planned_ids)
    if not ids or len(set(ids)) != len(ids):
        raise EvaluationError("Planned IDs must be unique and nonempty")
    if set(records) != set(ids):
        raise EvaluationError("Require one explicit record for every planned ID")
    return ids


def _scenario(record: Mapping):
    value = record["scenario"]
    return tuple(value) if isinstance(value, list) else value


def _mean(values) -> float:
    values = tuple(float(v) for v in values)
    if not values or not all(math.isfinite(v) for v in values):
        raise EvaluationError("Mean needs nonempty finite observations")
    # Divide before summation so a sum of large finite losses cannot overflow.
    result = math.fsum(v / len(values) for v in values)
    if not math.isfinite(result):
        raise EvaluationError("Nonfinite aggregate")
    return result


def _bins(record: Mapping) -> tuple[np.ndarray, np.ndarray, float, float]:
    starts = np.asarray(record["starts"], dtype=float)
    ends = np.asarray(record["ends"], dtype=float)
    tau = float(record["tau"])
    warmup = float(record.get("warmup_end", 180.0))
    if (starts.ndim != 1 or ends.shape != starts.shape
            or not np.isfinite(starts).all() or not np.isfinite(ends).all()
            or not math.isfinite(tau) or not math.isfinite(warmup)
            or np.any(ends <= starts) or np.any(starts[1:] < ends[:-1])):
        raise EvaluationError("Invalid, overlapping, or unordered bin boundaries")
    return starts, ends, tau, warmup


def _score_arrays(record: Mapping):
    starts, ends, tau, warmup = _bins(record)
    scores = np.asarray(record["scores"], dtype=float)
    if scores.shape != starts.shape:
        raise EvaluationError("Scalar system score required for every planned bin")
    if not record.get("failed", False) and (np.isinf(scores).any()
                                            or np.any(scores[np.isfinite(scores)] < 0)):
        raise EvaluationError("Infinite/negative score is not data unavailability")
    finite = (np.zeros(scores.shape, dtype=bool) if record.get("failed", False)
              else np.isfinite(scores))
    after = starts >= warmup
    normal = after & (ends <= tau)
    positive = after & (starts >= tau)
    straddle = after & ~(normal | positive)
    return starts, ends, scores, finite, normal, positive, straddle


def weighted_cdf_inverse(values, weights, q: float) -> float:
    """Exact discrete inverse; rational hierarchy weights avoid CDF rounding ties.

    Ordinary float weights are interpreted as their decimal string values.
    This is not NumPy/type-7 interpolated percentile behavior.
    """
    values = tuple(float(v) for v in values)
    weights = tuple(w if isinstance(w, Fraction) else Fraction(str(w)) for w in weights)
    level = Fraction(str(q))
    if (not values or len(values) != len(weights) or not 0 < level <= 1
            or not all(math.isfinite(v) for v in values)
            or any(w <= 0 for w in weights)):
        raise EvaluationError("Invalid weighted CDF arguments")
    total = sum(weights, Fraction())
    cumulative = Fraction()
    for value, weight in sorted(zip(values, weights), key=lambda pair: pair[0]):
        cumulative += weight
        if cumulative >= level * total:
            return value
    raise AssertionError("Positive finite weighted CDF must reach q")


def normal_score_distribution(cases: Mapping, planned_ids: Sequence) -> dict:
    """Equal scored-scenario -> scored-case -> valid normal endpoint weights.

    TD gates are fixed at 100 endpoints and 80% planned training cases. The
    returned IDs allow the controller to persist the exact fitting support.
    """
    ids = _ids(cases, planned_ids)
    groups = defaultdict(list)
    normal_by_case = {}
    for case_id in ids:
        _, ends, scores, finite, normal, _, _ = _score_arrays(cases[case_id])
        positions = np.flatnonzero(finite & normal)
        normal_by_case[case_id] = positions
        if len(positions):
            groups[_scenario(cases[case_id])].append(case_id)
    scored_cases = sum(len(group) for group in groups.values())
    endpoints = sum(len(indices) for indices in normal_by_case.values())
    if endpoints < 100 or 5 * scored_cases < 4 * len(ids):
        raise CoverageError(
            f"Threshold gate: {endpoints} normal endpoints; {scored_cases}/{len(ids)} cases")
    values, weights, support = [], [], []
    for scenario, case_ids in groups.items():
        for case_id in case_ids:
            positions = normal_by_case[case_id]
            weight = Fraction(1, len(groups) * len(case_ids) * len(positions))
            for position in positions:
                values.append(float(cases[case_id]["scores"][position]))
                weights.append(weight)
                support.append((case_id, int(position), float(cases[case_id]["ends"][position])))
    if sum(weights, Fraction()) != 1:
        raise AssertionError("Hierarchical CDF weights must sum exactly to one")
    return {"values": values, "weights": weights, "support_ids": support,
            "planned_cases": len(ids), "scored_cases": scored_cases,
            "scored_scenarios": len(groups), "normal_endpoints": endpoints,
            "case_coverage": scored_cases / len(ids)}


def calibrate_threshold(cases: Mapping, planned_ids: Sequence, q: float) -> dict:
    distribution = normal_score_distribution(cases, planned_ids)
    threshold = weighted_cdf_inverse(distribution["values"], distribution["weights"], q)
    return {**distribution, "q": float(q), "threshold": threshold,
            "weights": [float(w) for w in distribution["weights"]]}


def fixed_eligible_forecast_loss(inputs: Mapping, predictions: Mapping,
                                 planned_ids: Sequence) -> dict:
    """MAE of normalized targets BEFORE residual scaling, on frozen input IDs.

    inputs[id]: scenario, starts, ends, tau, optional warmup_end, targets[T,...],
    eligible[T,...]. predictions[id] has the exact targets shape. All remaining
    dimensions are channels, including service/channel pairs. Nonfinite values
    outside eligibility never become new observations; inside they are errors.
    """
    ids = _ids(inputs, planned_ids)
    _ids(predictions, ids)
    case_losses, support, per_bin = {}, {}, {}
    for case_id in ids:
        record = inputs[case_id]
        starts, ends, tau, warmup = _bins(record)
        target = np.asarray(record["targets"], dtype=float)
        prediction = np.asarray(predictions[case_id], dtype=float)
        eligible = np.asarray(record["eligible"])
        if (target.ndim < 2 or target.shape[0] != len(starts)
                or prediction.shape != target.shape or eligible.shape != target.shape
                or eligible.dtype != np.bool_):
            raise EvaluationError("Fixed forecast target/prediction/mask shape mismatch")
        channels = math.prod(target.shape[1:])
        target = target.reshape(len(starts), channels)
        prediction = prediction.reshape(target.shape)
        eligible = eligible.reshape(target.shape)
        selected = eligible & ((starts >= warmup) & (ends <= tau))[:, None]
        if not np.isfinite(target[selected]).all():
            raise EvaluationError("Input eligibility includes a nonfinite target")
        if not np.isfinite(prediction[selected]).all():
            raise EvaluationError(f"Nonfinite prediction on fixed eligible IDs: {case_id}")
        bin_losses = []
        selected_ids = []
        for b in np.flatnonzero(selected.any(axis=1)):
            channels = np.flatnonzero(selected[b])
            # Python scalar difference can overflow to inf; it is an explicit
            # numerical error, not an invitation to shrink the scoring mask.
            losses = [abs(float(target[b, c]) - float(prediction[b, c])) for c in channels]
            bin_losses.append(_mean(losses))
            selected_ids.extend((int(b), int(c)) for c in channels)
        support[case_id] = selected_ids
        per_bin[case_id] = bin_losses
        if bin_losses:
            case_losses[case_id] = _mean(bin_losses)
    if 5 * len(case_losses) < 4 * len(ids):
        raise CoverageError(f"Forecast eligibility gate: {len(case_losses)}/{len(ids)} cases")
    by_scenario = defaultdict(list)
    for case_id, value in case_losses.items():
        by_scenario[_scenario(inputs[case_id])].append(value)
    scenario_losses = {s: _mean(values) for s, values in by_scenario.items()}
    return {"loss": _mean(scenario_losses.values()), "case_losses": case_losses,
            "scenario_losses": [{"scenario": s, "loss": value}
                                for s, value in scenario_losses.items()], "bin_losses": per_bin,
            "support_ids": support, "planned_cases": len(ids),
            "eligible_cases": len(case_losses), "case_coverage": len(case_losses) / len(ids)}


def select_registered(objectives: Mapping, preference: Sequence, *, maximize=False):
    """TD absolute 1e-12 tie rule, preference first, lexical ID second."""
    if not objectives or not all(math.isfinite(float(v)) for v in objectives.values()):
        raise EvaluationError("Every registered objective must be finite before selection")
    optimum = (max if maximize else min)(float(v) for v in objectives.values())
    tied = [key for key, value in objectives.items() if abs(float(value) - optimum) <= 1e-12]
    priority = {key: i for i, key in enumerate(preference)}
    return min(tied, key=lambda key: (priority.get(key, len(priority)), str(key)))


def grouped_folds(cases: Mapping, planned_ids: Sequence,
                  folds=REGISTERED_FOLDS) -> list[dict]:
    ids = _ids(cases, planned_ids)
    normalized = [tuple(tuple(s) if isinstance(s, list) else s for s in fold) for fold in folds]
    all_scenarios = [s for fold in normalized for s in fold]
    if len(normalized) != 5 or len(set(all_scenarios)) != len(all_scenarios):
        raise EvaluationError("Require five disjoint scenario folds")
    if not {_scenario(cases[i]) for i in ids}.issubset(set(all_scenarios)):
        raise EvaluationError("Case scenario is absent from registered folds")
    result = []
    for index, held in enumerate(normalized):
        validation = tuple(i for i in ids if _scenario(cases[i]) in held)
        training = tuple(i for i in ids if _scenario(cases[i]) not in held)
        if not validation or not training:
            raise EvaluationError("Empty training or held-out fold")
        result.append({"fold": index + 1, "train_ids": training, "heldout_ids": validation})
    return result


def select_lambda(inputs: Mapping, predictions_by_lambda: Mapping,
                  planned_ids: Sequence, *, folds=REGISTERED_FOLDS) -> dict:
    """Joint G/L/ALL equal-arm loss; case-prefix models need no cross-case refit.

    Each planned case supplies held-out observations exactly once through the
    grouped roster. A numeric failure rejects selection pending correction;
    it does not make the remaining lambda values apparent winners.
    """
    ids = _ids(inputs, planned_ids)
    split = grouped_folds(inputs, ids, folds)
    if set(predictions_by_lambda) != set(LAMBDA_PRIORITY):
        raise EvaluationError("Require all three registered lambda candidates")
    results, objectives = {}, {}
    for lam, arms in predictions_by_lambda.items():
        if set(arms) != set(ARMS):
            raise EvaluationError("Common lambda selection requires exactly G/L/ALL")
        arm_results = {arm: fixed_eligible_forecast_loss(inputs, arms[arm], ids) for arm in ARMS}
        # The common input map fixes target IDs before any arm's predictions.
        objectives[lam] = _mean(result["loss"] for result in arm_results.values())
        fold_losses = []
        for fold in split:
            held = fold["heldout_ids"]
            by_arm = {}
            for arm in ARMS:
                scenario_values = defaultdict(list)
                for case_id in held:
                    if case_id in arm_results[arm]["case_losses"]:
                        scenario_values[_scenario(inputs[case_id])].append(
                            arm_results[arm]["case_losses"][case_id])
                by_arm[arm] = (_mean(_mean(v) for v in scenario_values.values())
                               if scenario_values else None)
            fold_losses.append({**fold, "arm_losses": by_arm})
        results[lam] = {"arms": arm_results, "folds": fold_losses}
    selected = select_registered(objectives, LAMBDA_PRIORITY)
    return {"selected_lambda": selected, "objectives": objectives, "details": results,
            "objective": "equal eligible scenario/case/bin/channel; equal G/L/ALL"}


def regime_metrics(case: Mapping, threshold: float) -> dict:
    """Per-case injection-regime metrics; unavailable never becomes negative."""
    if not math.isfinite(float(threshold)):
        raise EvaluationError("Threshold must be finite")
    starts, ends, scores, finite, normal, positive, straddle = _score_arrays(case)
    planned = normal | positive
    valid = finite & planned
    predicted = scores > threshold
    tp = int(np.sum(valid & positive & predicted))
    fp = int(np.sum(valid & normal & predicted))
    fn = int(np.sum(valid & positive & ~predicted))
    tn = int(np.sum(valid & normal & ~predicted))
    pden, rden, fden = tp + fp, tp + fn, 2 * tp + fp + fn
    return {"precision": tp / pden if pden else 0.0,
            "recall": tp / rden if rden else 0.0,
            "f1": 2 * tp / fden if fden else 0.0,
            "tp": tp, "fp": fp, "fn": fn, "tn": tn,
            "precision_undefined": pden == 0, "recall_undefined": rden == 0,
            "f1_undefined": fden == 0, "no_scorable_bins": not valid.any(),
            "failed": bool(case.get("failed", False)),
            "planned_bins": int(planned.sum()), "scored_bins": int(valid.sum()),
            "unavailable_bins": int((planned & ~finite).sum()),
            "excluded_straddle_bins": int(straddle.sum()),
            "normal_planned": int(normal.sum()), "normal_scored": int((normal & finite).sum()),
            "positive_planned": int(positive.sum()), "positive_scored": int((positive & finite).sum()),
            "coverage": float(valid.sum() / planned.sum()) if planned.any() else 0.0,
            "normal_observed_seconds": float(np.sum((ends - starts)[normal])),
            "normal_scored_seconds": float(np.sum((ends - starts)[normal & finite]))}


def planned_regime_summary(outcomes: Mapping, planned_ids: Sequence) -> dict:
    ids = _ids(outcomes, planned_ids)
    macro = {metric: _mean(outcomes[i][metric] for i in ids)
             for metric in ("precision", "recall", "f1")}
    totals = {field: sum(int(outcomes[i][field]) for i in ids)
              for field in ("tp", "fp", "fn", "tn", "planned_bins", "scored_bins",
                            "unavailable_bins", "excluded_straddle_bins",
                            "normal_planned", "normal_scored", "positive_planned", "positive_scored")}
    tp, fp, fn = (totals[key] for key in ("tp", "fp", "fn"))
    return {"macro": macro, "totals": totals, "planned_cases": len(ids),
            "scored_cases": sum(not outcomes[i]["no_scorable_bins"] for i in ids),
            "failed_cases": sum(outcomes[i]["failed"] for i in ids),
            "pooled_precision": tp / (tp + fp) if tp + fp else 0.0,
            "pooled_recall": tp / (tp + fn) if tp + fn else 0.0,
            "pooled_f1": 2 * tp / (2 * tp + fp + fn) if 2 * tp + fp + fn else 0.0}


def select_q(cases: Mapping, planned_ids: Sequence, *, folds=REGISTERED_FOLDS,
             q_values=Q_REGISTRY) -> dict:
    """Fold-training CDFs, held-out macro case F1, then full-development refit."""
    ids = _ids(cases, planned_ids)
    if set(q_values) != set(Q_REGISTRY):
        raise EvaluationError("Primary q selection requires all registered candidates")
    split = grouped_folds(cases, ids, folds)
    distributions = []
    for fold in split:
        training = {i: cases[i] for i in fold["train_ids"]}
        distributions.append(normal_score_distribution(training, fold["train_ids"]))
    details, objectives = {}, {}
    for q in q_values:
        outcomes, fold_reports = {}, []
        for fold, distribution in zip(split, distributions):
            threshold = weighted_cdf_inverse(distribution["values"], distribution["weights"], q)
            for case_id in fold["heldout_ids"]:
                outcomes[case_id] = regime_metrics(cases[case_id], threshold)
            fold_reports.append({**fold, "threshold": threshold,
                                 "normal_support_ids": distribution["support_ids"],
                                 "normal_endpoints": distribution["normal_endpoints"],
                                 "case_coverage": distribution["case_coverage"]})
        summary = planned_regime_summary(outcomes, ids)
        objectives[q] = summary["macro"]["f1"]
        details[q] = {"folds": fold_reports, "cases": outcomes, "summary": summary}
    if not any(not outcome["f1_undefined"] for detail in details.values()
               for outcome in detail["cases"].values()):
        raise CoverageError("All held-out regime-F1 objectives are undefined")
    selected = select_registered(objectives, sorted(q_values, reverse=True), maximize=True)
    return {"selected_q": selected, "objectives": objectives, "details": details,
            "full_development_calibration": calibrate_threshold(cases, ids, selected)}


def mean_planned_draw_metrics(draws: Mapping, *, planned_draws: int = 256) -> dict:
    """Mean per-draw METRICS, with explicit None failures; never average scores."""
    if planned_draws < 2 or set(draws) != set(range(planned_draws)):
        raise EvaluationError("Every planned draw needs an explicit metric record or None failure")
    result, mc = {}, {}
    for metric in RANK_METRICS:
        values = [0.0 if draws[j] is None else float(draws[j][metric]) for j in range(planned_draws)]
        if not all(math.isfinite(v) and 0 <= v <= 1 for v in values):
            raise EvaluationError("Invalid ranking metric; record an explicit failed draw")
        mean = _mean(values)
        sd = math.sqrt(math.fsum((value - mean) ** 2 for value in values) / (planned_draws - 1))
        result[metric] = mean
        mc[metric] = {"sd": sd, "se": sd / math.sqrt(planned_draws)}
    return {"metrics": result, "mc": mc, "planned_draws": planned_draws,
            "failed_draws": sum(draw is None for draw in draws.values()),
            "interpretation": "conditional draw variability, not incident independence or mixing proof"}


def event_diagnostics(trigger_endpoints, case: Mapping) -> dict:
    """Descriptive replay events. Endpoint == tau is pre-injection (end<=tau).

    Report both observed-duration and scored-duration rates explicitly. They
    are archival injection-regime descriptors, never operational false alarms.
    """
    times = tuple(float(t) for t in trigger_endpoints)
    if (not all(math.isfinite(t) for t in times) or any(b <= a for a, b in zip(times, times[1:]))):
        raise EvaluationError("Triggers must be strictly ordered finite endpoints")
    _, ends, _, finite, normal, positive, straddle = _score_arrays(case)
    if not set(times).issubset(set(float(t) for t in ends[finite & (normal | positive | straddle)])):
        raise EvaluationError("Trigger must belong to a valid observed score endpoint")
    tau = float(case["tau"])
    metrics = regime_metrics(case, 0.0)
    pre = [t for t in times if t <= tau]
    post = [t for t in times if t > tau]
    observed_hours = metrics["normal_observed_seconds"] / 3600
    scored_hours = metrics["normal_scored_seconds"] / 3600
    return {"triggers": list(times), "pre_injection_triggers": len(pre),
            "observed_normal_hours": observed_hours, "scored_normal_hours": scored_hours,
            "rate_per_observed_normal_hour": len(pre) / observed_hours if observed_hours else None,
            "rate_per_scored_normal_hour": len(pre) / scored_hours if scored_hours else None,
            "first_post_injection_trigger": post[0] if post else None,
            "first_post_injection_delay": post[0] - tau if post else None,
            "post_injection_censored": not bool(post)}


def first_trigger_composition(triggers: Sequence[Mapping], tau: float,
                              *, history_seconds: float = 360.0) -> dict:
    """Use only first post-injection trigger; failures/history deficits stay zero.

    Trigger record: endpoint, status, and metrics with rr/hit1/hit3/hit5/ndcg5.
    Metrics are already produced by the trusted tie evaluator. No later rescue.
    """
    endpoints = [float(record["endpoint"]) for record in triggers]
    if (not math.isfinite(tau) or not all(math.isfinite(t) for t in endpoints)
            or any(b <= a for a, b in zip(endpoints, endpoints[1:]))):
        raise EvaluationError("Composition requires ordered finite trigger endpoints")
    zero = dict.fromkeys(RANK_METRICS, 0.0)
    first = next((record for record in triggers if float(record["endpoint"]) > tau), None)
    if first is None:
        return {"metrics": zero, "status": "NO_POST_INJECTION_TRIGGER", "endpoint": None}
    endpoint = float(first["endpoint"])
    if endpoint < history_seconds:
        return {"metrics": zero, "status": "INSUFFICIENT_HISTORY", "endpoint": endpoint}
    if first.get("status") != "VALID":
        return {"metrics": zero, "status": first.get("status", "METHOD_FAILURE"), "endpoint": endpoint}
    metrics = {name: float(first["metrics"][name]) for name in RANK_METRICS}
    if not all(math.isfinite(value) and 0 <= value <= 1 for value in metrics.values()):
        raise EvaluationError("Invalid composed ranking metrics")
    return {"metrics": metrics, "status": "VALID", "endpoint": endpoint}


def leave_one_cell_reselection(cases: Mapping, planned_ids: Sequence,
                               selector: Callable[[dict, tuple], dict]) -> dict:
    """Rerun an explicit caller selector per deletion; never relabel fixed scores.

    The callback must refit fold/full calibration if selecting q. Failure is
    retained with its type/message. This diagnostic does not replace primary.
    """
    ids = _ids(cases, planned_ids)
    results = []
    for scenario in sorted({_scenario(cases[i]) for i in ids}, key=str):
        kept = tuple(i for i in ids if _scenario(cases[i]) != scenario)
        subset = {i: cases[i] for i in kept}
        try:
            result = {"status": "VALID", "selection": selector(subset, kept)}
        except EvaluationError as error:
            result = {"status": "INVALID", "error_type": type(error).__name__, "error": str(error)}
        results.append({"excluded_scenario": scenario, "kept_cases": len(kept), **result})
    return {"deletions": results, "primary_registry_changed": False}

"""Declared TD12 comparator adapters; no fallback rankings or GT access.

RCD execution requires an injected, externally qualified, pinned/patched bare
upstream function. This module never imports an arbitrary installed RCAEval.
"""

import numpy as np

from .ranking import _channel_types, local_scores


def baro_scores(ref, query, channel_types, floor=.01):
    """Paper-component BARO adaptation: absolute temporal MAX, then service MAX.

    Uses common TD reference/query metric bins, finite-bin eligibility, type-7
    quantiles and the selected study-specific floor. No MBOCPD, count evidence,
    upstream domain filters, constant dropping or signed-max code path is used.
    Returns scores plus the same numeric diagnostics as local_scores.
    """
    ref, query = np.asarray(ref, dtype=np.float64), np.asarray(query, dtype=np.float64)
    if ref.ndim != 3 or query.ndim != 3 or ref.shape[:2] != query.shape[:2]:
        raise ValueError("ref/query must have matching N,K and three dimensions")
    types = _channel_types(channel_types, ref.shape[1])
    js = [j for j, kind in enumerate(types) if kind == "metric"]
    result = local_scores(ref[:, js, :], query[:, js, :], [0] * len(js),
                          {"floor": floor, "pool": "max", "fusion": "max",
                           "temporal": "max", "cap": None, "include_logs": False})
    result["scores"] = result["blocks"]["metric"].copy()
    result["method"] = "BARO-RANK-adapted-TD12"
    return result


def local_max_scores(blocks, block_masks):
    """Mandatory Local-MAX-MT context, retaining unavailable-zero masks."""
    m, t = np.asarray(blocks["metric"]), np.asarray(blocks["trace"])
    mm, tm = np.asarray(block_masks["metric"], dtype=bool), np.asarray(
        block_masks["trace"], dtype=bool)
    if m.ndim != 1 or m.shape != t.shape or m.shape != mm.shape or m.shape != tm.shape:
        raise ValueError("MT blocks/masks must be matching vectors")
    if not np.isfinite(m).all() or not np.isfinite(t).all() or (m < 0).any() or (t < 0).any():
        raise ValueError("MT blocks must be finite nonnegative placeholders")
    return {"scores": np.maximum(np.where(mm, m, 0.), np.where(tm, t, 0.)),
            "mask": mm | tm, "method": "Local-MAX-MT"}


def rcd_run(dataframe, seed=420, bins=5, *, upstream_rcd):
    """Execute qualified bare RCD on a trusted 600-row opaque numeric frame.

    time must be exactly relative seconds 0..599; boundary300 is used only for
    slicing and the source patch drops time immediately afterward. All other
    columns are numeric opaque metric keys; owner mapping stays in the trusted
    caller. Inputs are already eligibility-checked and reference-median-imputed.
    Parameters are gamma5/localizedTrue/datasetNone/dk_select_usefulFalse.
    Each seed must run sequentially or in its own process, not shared threads.
    A valid empty ranks list is preserved for all-V worst-tie padding by caller;
    exceptions/duplicate metric keys/malformed output are explicit failures.
    No root labels, epoch, service vocabulary or owner mapping are accepted.
    """
    def failure(reason, message=None):
        return {"method": "RCD-RCAEval-adapted-TD12", "seed": seed, "bins": bins,
                "status": "FAILURE", "ranks": None, "reason": reason,
                "error": message}

    if not callable(upstream_rcd):
        return failure("unqualified_upstream_callable")
    if seed not in (420, 421, 422) or bins not in (3, 5, 7):
        return failure("unregistered_seed_or_bins")
    if "time" not in dataframe.columns or dataframe.columns.duplicated().any():
        return failure("missing_time_or_duplicate_columns")
    columns = [c for c in dataframe.columns if c != "time"]
    if not columns:
        return failure("no_eligible_columns")
    if any(not isinstance(c, str) or not c or c == "F-node" for c in columns):
        return failure("invalid_metric_key")
    try:
        times = dataframe["time"].to_numpy(dtype=np.float64)
        values = dataframe[columns].to_numpy(dtype=np.float64)
    except (TypeError, ValueError):
        return failure("nonnumeric_input")
    if not np.array_equal(times, np.arange(600, dtype=np.float64)):
        return failure("invalid_relative_grid")
    if not np.isfinite(values).all():
        return failure("nonfinite_after_imputation")
    try:
        result = upstream_rcd(dataframe.copy(deep=True), 300,
                              dk_select_useful=False, gamma=5, localized=True,
                              bins=bins, verbose=False, dataset=None, seed=seed)
    except Exception as exc:
        # Deliberately exclude exception text: third-party errors can carry
        # paths or identifiers. Trusted orchestration records sanitized details.
        return failure("upstream_exception", type(exc).__name__)
    if not isinstance(result, dict) or not isinstance(result.get("ranks"), (list, tuple)):
        return failure("malformed_output")
    ranks = list(result["ranks"])
    if any(not isinstance(c, str) or not c for c in ranks):
        return failure("unparseable_metric_rank")
    if len(set(ranks)) != len(ranks):
        return failure("duplicate_metric_rank")
    return {"method": "RCD-RCAEval-adapted-TD12", "seed": seed, "bins": bins,
            "status": "SUCCESS", "ranks": ranks, "reason": None, "error": None,
            "unknown_metric_keys": [c for c in ranks if c not in columns]}

"""Evaluator-side utilities; never imported by ranking/detection workers."""
from __future__ import annotations

import math
import numpy as np


def tie_metrics(scores, root_index, *, failed=False):
    values = np.asarray(scores, dtype=np.float64)
    zero = {'rr': 0.0, 'hit1': 0.0, 'hit3': 0.0, 'hit5': 0.0, 'ndcg5': 0.0}
    if failed:
        return {**zero, 'status': 'METHOD_FAILURE', 'tie_start': None, 'tie_end': None}
    if root_index is None or root_index < 0 or root_index >= len(values):
        return {**zero, 'status': 'ROOT_ABSENT', 'tie_start': None, 'tie_end': None}
    if values.ndim != 1 or not np.isfinite(values).all():
        raise ValueError('Invalid ranking output must be recorded as explicit method failure')
    # NumPy decimal scaling can overflow for finite uncapped comparator scores.
    # Python's float round preserves finite large magnitudes at positive ndigits.
    rounded = np.array([round(float(value), 12) for value in values])
    root = rounded[root_index]
    start = 1 + int(np.sum(rounded > root))
    end = start + int(np.sum(rounded == root)) - 1
    count = end - start + 1
    result = {'rr': sum(1 / r for r in range(start, end + 1)) / count,
              'ndcg5': sum(1 / math.log2(r + 1)
                           for r in range(start, min(end, 5) + 1)) / count,
              'status': 'VALID_TIE' if count > 1 else 'VALID_RANK',
              'tie_start': start, 'tie_end': end}
    for k in (1, 3, 5):
        result[f'hit{k}'] = max(0, min(end, k) - start + 1) / count
    return result


def planned_mean(outcomes, planned_ids, metric='rr'):
    if len(set(planned_ids)) != len(planned_ids) or not planned_ids:
        raise ValueError('Planned denominator must be unique and nonempty')
    if set(outcomes) != set(planned_ids):
        raise ValueError('Every planned ID must have an explicit outcome, including failures')
    return sum(float(outcomes[i][metric]) for i in planned_ids) / len(planned_ids)


def service_scores_from_metric_ranks(ranks, metric_owners, n_services):
    """RCD-only partial padding: success [] yields one complete worst tie."""
    if not isinstance(ranks, list) or any(not isinstance(k, str) for k in ranks):
        raise ValueError('Unparseable metric ranking')
    if len(ranks) != len(set(ranks)):
        raise ValueError('Duplicate metric keys in RCD output')
    selected, unknown = [], []
    for key in ranks:
        if key not in metric_owners:
            unknown.append(key)
        elif metric_owners[key] not in selected:
            selected.append(metric_owners[key])
    scores = np.zeros(n_services)
    for position, owner in enumerate(selected):
        if not isinstance(owner, int) or not 0 <= owner < n_services:
            raise ValueError('Invalid metric owner index')
        scores[owner] = len(selected) - position
    return scores, {'unknown_metric_keys': unknown, 'ranked_services': len(selected)}

"""Trusted receipts and lossless numeric artifacts for bounded development."""
from __future__ import annotations
import hashlib
import json
import math
import time
from pathlib import Path
import numpy as np


def plain(value):
    if isinstance(value, np.ndarray):
        return plain(value.tolist())
    if isinstance(value, np.generic):
        return plain(value.item())
    if isinstance(value, dict):
        return {str(k): plain(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [plain(v) for v in value]
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, float) and not math.isfinite(value):
        return None  # JSON audit only; lossless numeric files preserve NaN masks.
    return value


def save_json(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open('x', encoding='utf-8', newline='\n') as stream:
        json.dump(plain(value), stream, ensure_ascii=False, indent=2, allow_nan=False)
        stream.write('\n')


def save_npz(path, **arrays):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    converted = {k: np.asarray(v) for k, v in arrays.items()}
    if any(a.dtype.hasobject for a in converted.values()):
        raise ValueError('Object arrays are forbidden')
    with path.open('xb') as stream:
        np.savez_compressed(stream, **converted)


def failure(run, stage, case, exc):
    record = {'stage': stage, 'case': case, 'type': type(exc).__name__, 'message': str(exc)}
    with (Path(run) / 'failures.jsonl').open('a', encoding='utf-8') as stream:
        stream.write(json.dumps(record, ensure_ascii=False) + '\n')
    return record


def require_contract(run, stage_fragment=None):
    run = Path(run)
    contract = json.loads((run / 'run-contract.json').read_text(encoding='utf-8'))
    if stage_fragment and stage_fragment not in contract['stage']:
        raise ValueError('Wrong pre-recorded stage')
    return contract


def file_sha(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1048576), b''):
            h.update(block)
    return h.hexdigest()

"""Sequential numeric-only development transport for qualified pinned RCD.

Launch: isolated Python3.9 -m scripts.task_e.rcd_numeric_worker RUN_DIRECTORY
Each input line has exactly {"values": [[...], ...600 rows...], "configs":
[{"seed": 420, "bins": 3}, ...all nine registered combinations exactly once]}.
No metric/service names, case IDs, paths, labels, timestamps or owner map enter
the request. The controller has already enforced TD raw1s eligibility and
reference-median imputation. Relative time and opaque m0... columns are generated
here solely for the pinned wrapper's required split. Empty-width numeric input
is preserved as nine explicit no_eligible_columns failures.

The trusted bootstrap reads only the coordinator contract, its pinned successful
synthetic qualification report, and pinned code/environment metadata. Subsequent
requests never open a data file. This API separation is not an OS filesystem
sandbox. Per-config failure is retained; the worker neither selects a best seed
nor evaluates/averages predictions. Controller scores all three seeds, failures0,
using bins5 as primary and bins3/7 as the registered OFAT sensitivity.
"""
from __future__ import annotations

import hashlib
import json
import math
import sys
import time
from contextlib import redirect_stdout
from pathlib import Path

from .rcd_runtime import file_sha256, load_pinned_rcd, require_run_contract


SCHEMA = "TD13-RCD-NUMERIC-v1"
REGISTERED = frozenset((seed, bins) for bins in (3, 5, 7) for seed in (420, 421, 422))


class RequestError(ValueError):
    """A static, safe error code; never embed request contents in this message."""


def _object_without_duplicates(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise RequestError("duplicate_json_key")
        result[key] = value
    return result


def _reject_json_constant(_value):
    raise RequestError("nonfinite_json_number")


def parse_request(line):
    """Strict stdlib validation before creating a numeric array."""
    try:
        request = json.loads(line, object_pairs_hook=_object_without_duplicates,
                             parse_constant=_reject_json_constant)
    except (json.JSONDecodeError, RecursionError):
        raise RequestError("invalid_json") from None
    if type(request) is not dict or set(request) != {"values", "configs"}:
        raise RequestError("request_fields_must_be_values_and_configs")
    values, configs = request["values"], request["configs"]
    if type(values) is not list or len(values) != 600:
        raise RequestError("expected_600_numeric_rows")
    width = None
    for row in values:
        if type(row) is not list:
            raise RequestError("expected_numeric_row_lists")
        if width is None:
            width = len(row)
        if len(row) != width:
            raise RequestError("ragged_numeric_grid")
        for value in row:
            if type(value) not in (int, float):
                raise RequestError("grid_requires_numbers_without_objects_strings_or_booleans")
            try:
                finite = math.isfinite(value)
            except OverflowError:
                finite = False
            if not finite:
                raise RequestError("nonfinite_or_out_of_float64_range")
    if type(configs) is not list or len(configs) != 9:
        raise RequestError("all_nine_registered_seed_bin_configs_required")
    realized = []
    for config in configs:
        if type(config) is not dict or set(config) != {"seed", "bins"}:
            raise RequestError("config_fields_must_be_seed_and_bins")
        seed, bins = config["seed"], config["bins"]
        if type(seed) is not int or type(bins) is not int or (seed, bins) not in REGISTERED:
            raise RequestError("unregistered_seed_or_bins")
        realized.append((seed, bins))
    if len(set(realized)) != 9 or set(realized) != REGISTERED:
        raise RequestError("all_nine_configs_must_occur_once")
    return values, realized


def _require_qualification(workspace, contract):
    """Verify the real fixture evidence, never substitute a successful import."""
    pointer = contract["config"].get("rcd_qualification_report")
    if type(pointer) is not dict or set(pointer) != {"path", "sha256"}:
        raise RuntimeError("Run config must pin rcd_qualification_report path and sha256")
    report_path = Path(pointer["path"]).resolve()
    report_path.relative_to(workspace / "results/task-e")
    if report_path.name != "rcd-fixture-report.json" or file_sha256(report_path) != pointer["sha256"]:
        raise RuntimeError("Qualification report identity mismatch")
    report = json.loads(report_path.read_text(encoding="utf-8-sig"))
    if report.get("passed") is not True or report.get("tests_run", 0) < 4:
        raise RuntimeError("Real RCD qualification did not pass")
    if report.get("failures") != [] or report.get("errors") != []:
        raise RuntimeError("Qualification contains failures or errors")
    qualification_contract_path = report_path.parent / "run-contract.json"
    qualification_contract = json.loads(qualification_contract_path.read_text(encoding="utf-8-sig"))
    if qualification_contract["td"]["sha256"] != contract["td"]["sha256"]:
        raise RuntimeError("Qualification belongs to a different TD revision")
    if qualification_contract["config"].get("rcd_runtime_qualification_authorized") is not True:
        raise RuntimeError("Qualification was not coordinator-authorized")
    qualification_sources = {str(Path(row["path"]).resolve()): row["sha256"]
                             for row in qualification_contract["source_files"]}
    current_sources = {str(Path(row["path"]).resolve()): row["sha256"]
                       for row in contract["source_files"]}
    for relative in ("scripts/task_e/rcd_runtime.py", "scripts/task_e/comparators.py",
                     "tests/task_e/test_rcd_runtime.py"):
        source = workspace / relative
        if qualification_sources.get(str(source)) != file_sha256(source):
            raise RuntimeError("Qualification source changed or was not pinned: " + relative)
    worker = Path(__file__).resolve()
    if current_sources.get(str(worker)) != file_sha256(worker):
        raise RuntimeError("Numeric worker must be pinned in the current run contract")
    records = report.get("numeric_runs", [])
    if len(records) != 20:
        raise RuntimeError("Expected 18 seeded runs, real empty run and injected CI failure")
    grouped = {}
    for record in records:
        key = (record.get("fixture"), record.get("seed"), record.get("bins"))
        if key in grouped or not record.get("ci_calls") or record.get("ci_call_count", 0) < 1:
            raise RuntimeError("Qualification lacks unique real CI execution receipts")
        grouped[key] = record
    expected_keys = {(name, seed, bins) for name in ("separated-shift", "separated-shift-repeat")
                     for seed, bins in REGISTERED}
    expected_keys |= {("identical-halves", 420, 5), ("injected-CI-exception", 420, 5)}
    if set(grouped) != expected_keys:
        raise RuntimeError("Qualification did not cover the required seed/bin grid")
    for seed, bins in REGISTERED:
        first = grouped[("separated-shift", seed, bins)]
        repeat = grouped[("separated-shift-repeat", seed, bins)]
        if (first["result"].get("status") != "SUCCESS"
                or first["result"].get("ranks") != ["m000"]
                or first["result"] != repeat["result"]
                or first["ci_calls"] != repeat["ci_calls"]):
            raise RuntimeError("Real seeded qualification or determinism failed")
    empty = grouped[("identical-halves", 420, 5)]["result"]
    injected = grouped[("injected-CI-exception", 420, 5)]["result"]
    if empty.get("status") != "SUCCESS" or empty.get("ranks") != []:
        raise RuntimeError("Valid empty-ranking qualification failed")
    if (injected.get("status") != "FAILURE" or injected.get("ranks") is not None
            or injected.get("reason") != "upstream_exception"):
        raise RuntimeError("Explicit exception qualification failed")
    return report, {"report_sha256": pointer["sha256"],
                    "qualification_run_id": qualification_contract["run_id"],
                    "qualification_contract_sha256": file_sha256(qualification_contract_path)}


def bootstrap(run_dir):
    workspace, contract = require_run_contract(run_dir)
    qualification, qualification_identity = _require_qualification(workspace, contract)
    # Import output is also kept off the line-JSON transport.
    with redirect_stdout(sys.stderr):
        loaded = load_pinned_rcd(run_dir, workspace)
        import numpy as np
        import pandas as pd
        from .comparators import rcd_run
    earlier, now = qualification["provenance"], loaded.provenance
    for key in ("source_manifest_sha256", "patch_sha256", "original_rcd_sha256",
                "patched_rcd_sha256", "packages", "customized_installed_files", "python", "executable"):
        if earlier.get(key) != now.get(key):
            raise RuntimeError("Current RCD runtime differs from successful qualification: " + key)
    metadata = {
        "method": "RCD-RCAEval-adapted-TD12", **qualification_identity,
        "source_manifest_sha256": now["source_manifest_sha256"],
        "patch_sha256": now["patch_sha256"], "patched_rcd_sha256": now["patched_rcd_sha256"],
        "worker_sha256": file_sha256(__file__), "packages": now["packages"],
        "parameters": {"gamma": 5, "localized": True, "dk_select_useful": False,
                       "dataset": None, "LOCAL_ALPHA": .01, "START_ALPHA": .001,
                       "ALPHA_STEP": .1, "ALPHA_LIMIT": 1},
        "preprocessing": "controller eligible raw1s metrics; reference-median imputation; common-window kmeans",
        "time_policy": "manufactured relative0..599; split300; exact post-split time-drop patch",
        "transport": "numeric values/configs only; locally manufactured opaque column indices",
        "execution": "all nine configurations sequentially; wrapper resets numpy seed for every call",
        "aggregation": "none here; controller averages seeds420/421/422 with failed seeds0; primary bins5",
        "framework_init_executed": False,
        "limitations": "contextual adapted comparator; neither exact-paper reproduction nor trace-graph causal ground truth",
    }
    return loaded, np, pd, rcd_run, metadata


def run_request(values, configs, runtime):
    loaded, np, pd, rcd_run, metadata = runtime
    numeric = np.asarray(values, dtype=np.float64)
    if numeric.ndim != 2 or numeric.shape[0] != 600 or not np.isfinite(numeric).all():
        raise RequestError("invalid_float64_numeric_grid")
    keys = ["m" + str(index) for index in range(numeric.shape[1])]
    frame = pd.DataFrame(numeric, columns=keys)
    frame.insert(0, "time", np.arange(600, dtype=np.float64))
    indices = {key: index for index, key in enumerate(keys)}
    results = []
    for seed, bins in configs:
        start = time.perf_counter()
        try:
            with redirect_stdout(sys.stderr):
                result = rcd_run(frame, seed=seed, bins=bins, upstream_rcd=loaded.rcd)
        except Exception as exc:
            # An unexpected adapter error cannot erase the other planned draws.
            result = {"method": metadata["method"], "seed": seed, "bins": bins,
                      "status": "FAILURE", "ranks": None, "reason": "adapter_exception",
                      "error": type(exc).__name__}
        result["wall_seconds"] = time.perf_counter() - start
        result["metric_rank_indices"] = (None if result["ranks"] is None else
                                         [indices[key] for key in result["ranks"] if key in indices])
        results.append(result)
    return {"schema": SCHEMA, "status": "COMPLETE", "shape": list(numeric.shape),
            "input_numeric_sha256": hashlib.sha256(numeric.astype("<f8", copy=False).tobytes()).hexdigest(),
            "results": results, "fidelity": metadata}


def emit(value):
    sys.stdout.write(json.dumps(value, allow_nan=False, separators=(",", ":")) + "\n")
    sys.stdout.flush()


def main():
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python -m scripts.task_e.rcd_numeric_worker RUN_DIRECTORY")
    try:
        runtime = bootstrap(Path(sys.argv[1]).resolve())
    except Exception as exc:
        # Bootstrap receipts may contain trusted paths; emit type only, no echo.
        sys.stderr.write(json.dumps({"schema": SCHEMA, "status": "BOOTSTRAP_FAILURE",
                                     "error_type": type(exc).__name__}) + "\n")
        return 2
    for line in sys.stdin:
        try:
            values, configs = parse_request(line)
            response = run_request(values, configs, runtime)
        except RequestError as exc:
            response = {"schema": SCHEMA, "status": "REQUEST_FAILURE",
                        "reason": str(exc), "results": None}
        except Exception as exc:
            response = {"schema": SCHEMA, "status": "WORKER_FAILURE",
                        "error_type": type(exc).__name__, "results": None}
        emit(response)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Numeric-only Task E child process and strict, non-pickle wire protocol.

This module never imports controller, loader, evaluator, source manifests or
cache code. A dedicated Python entry point avoids spawn importing the campaign
as __main__. Process/API separation is not a hostile-code OS filesystem sandbox.
"""
from __future__ import annotations

import hashlib
import io
import json
import struct
import sys

import numpy as np

from scripts.task_e.detection import fit_detector, score_bin, _config
from scripts.task_e.ranking import local_scores, rank_scores

WIRE_SCHEMA = "TD13-NUMERIC-WIRE-v1"
MAX_WIRE_BYTES = 512 * 1024 * 1024


class ProtocolError(ValueError):
    pass


def _array(value, label, dimensions=None, boolean=False, allow_missing=True):
    if not isinstance(value, np.ndarray) or value.dtype.kind not in "biuf":
        raise ProtocolError(f"{label} requires a numeric ndarray; object/string arrays forbidden")
    if dimensions is not None and value.ndim not in dimensions:
        raise ProtocolError(f"{label} has an invalid number of axes")
    if boolean and value.dtype != np.bool_:
        raise ProtocolError(f"{label} requires a boolean mask")
    if np.isinf(value).any() or (not allow_missing and not np.isfinite(value).all()):
        raise ProtocolError(f"{label} has forbidden nonfinite input")
    return value


def _fields(message, required, optional=()):
    if not isinstance(message, dict) or set(message) - set(required) - set(optional):
        raise ProtocolError("Unknown message field: labels, epochs, names, paths and metadata are forbidden")
    if set(required) - set(message):
        raise ProtocolError("Missing required numeric protocol field")


def _local_config(config):
    allowed = {"floor", "pool", "fusion", "temporal", "cap", "include_logs"}
    if not isinstance(config, dict) or set(config) - allowed:
        raise ProtocolError("Unknown local configuration field")
    if config.get("floor", .01) not in (.0001, .001, .01):
        raise ProtocolError("Unregistered local scale floor")
    if config.get("pool", "max") not in ("max", "q90") or config.get("temporal", "q90") not in ("max", "q90"):
        raise ProtocolError("Unregistered local pooling")
    if config.get("fusion", "max") not in ("max", "availablemean"):
        raise ProtocolError("Unregistered local fusion")
    if config.get("cap") not in (None, 20):
        raise ProtocolError("Unregistered historical cap")
    if "include_logs" in config and not isinstance(config["include_logs"], bool):
        raise ProtocolError("include_logs must be boolean")


def _rank_configs(configs):
    if not isinstance(configs, list) or not configs:
        raise ProtocolError("Ranking configs must be a nonempty list")
    for config in configs:
        if not isinstance(config, dict) or set(config) - {"operator", "direction", "damping"}:
            raise ProtocolError("Unknown ranking configuration field")
        operator = config.get("operator", "ppr")
        direction = config.get("direction", "reverse")
        if operator not in ("ppr", "diffusion") or direction not in ("reverse", "undirected"):
            raise ProtocolError("Unregistered ranking operator/direction")
        if operator == "diffusion" and direction != "undirected":
            raise ProtocolError("Diffusion requires its registered undirected projection")
        if config.get("damping", .85) not in (.2, .5, .85):
            raise ProtocolError("Unregistered ranking parameter")


def validate_request(message):
    """Fail closed on a finite schema before any numeric function is invoked."""
    if not isinstance(message, dict) or not isinstance(message.get("op"), str):
        raise ProtocolError("Request must name one registered operation")
    op = message["op"]
    if op in ("ping", "close"):
        _fields(message, {"op"})
    elif op == "fit_c5":
        _fields(message, {"op", "warmup", "adj", "channel_types", "fit_service_mask", "configs"})
        values = _array(message["warmup"], "warmup", (3,))
        adjacency = _array(message["adj"], "adj", (2,), allow_missing=False)
        types = _array(message["channel_types"], "channel_types", (1,), allow_missing=False)
        services = _array(message["fit_service_mask"], "fit_service_mask", (1,), boolean=True)
        if not isinstance(message["configs"], list) or not message["configs"]:
            raise ProtocolError("Detector configs must be a nonempty list")
        configs = [_config(config) for config in message["configs"]]
        for config in configs:
            if len(values) != config["fit_bins"] + config["cal_bins"]:
                raise ProtocolError("Only the exact registered warmup is admitted, never a future suffix")
        if len({(cfg["bin_seconds"], cfg["fit_bins"], cfg["cal_bins"]) for cfg in configs}) != 1:
            raise ProtocolError("One C5 session needs one common chronological bin/prefix grid")
        if (adjacency.shape != (values.shape[1], values.shape[1]) or
                services.shape != (values.shape[1],) or types.shape != (values.shape[2],)):
            raise ProtocolError("Inconsistent numeric C5 axes")
    elif op == "score_c5":
        _fields(message, {"op", "values", "bin_index"})
        _array(message["values"], "current_bin", (2,))
        if type(message["bin_index"]) is not int or message["bin_index"] < 0:
            raise ProtocolError("bin_index must be a relative nonnegative index")
    elif op == "c1":
        _fields(message, {"op", "ref", "query", "adj", "channel_types", "local_config"}, {"rank_configs"})
        ref = _array(message["ref"], "ref", (3,))
        query = _array(message["query"], "query", (3,))
        _array(message["adj"], "adj", (2,), allow_missing=False)
        _array(message["channel_types"], "channel_types", (1,), allow_missing=False)
        if ref.shape[:2] != query.shape[:2]:
            raise ProtocolError("C1 numeric input axes disagree")
        _local_config(message["local_config"])
        if message.get("rank_configs"):
            _rank_configs(message["rank_configs"])
    elif op == "rank":
        _fields(message, {"op", "local", "adj", "configs"})
        _array(message["local"], "local", (1,), allow_missing=False)
        _array(message["adj"], "adj", (2, 3), allow_missing=False)
        _rank_configs(message["configs"])
    else:
        raise ProtocolError("Unregistered operation")
    return message


def _encode(value, arrays):
    if isinstance(value, np.ndarray):
        if value.dtype.kind not in "biuf":
            raise ProtocolError("Wire arrays must be numeric; pickle/object arrays forbidden")
        key = f"a{len(arrays)}"
        arrays[key] = np.ascontiguousarray(value)
        return {"__array__": key}
    if isinstance(value, np.generic):
        value = value.item()
    if isinstance(value, float) and not np.isfinite(value):
        return {"__float__": "nan" if np.isnan(value) else "inf" if value > 0 else "-inf"}
    if isinstance(value, dict):
        if any(not isinstance(k, str) for k in value):
            raise ProtocolError("Wire object keys must be strings")
        return {k: _encode(v, arrays) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [_encode(v, arrays) for v in value]
    if value is None or type(value) in (str, int, float, bool):
        return value
    raise ProtocolError("Unsupported wire object")


def encode_message(value):
    """NPZ numeric arrays plus JSON structure; no executable deserialization."""
    arrays = {}
    tree = _encode(value, arrays)
    manifest = json.dumps({"schema": WIRE_SCHEMA, "tree": tree}, allow_nan=False,
                          separators=(",", ":")).encode()
    arrays["__manifest__"] = np.frombuffer(manifest, dtype=np.uint8)
    stream = io.BytesIO()
    np.savez(stream, **arrays)
    payload = stream.getvalue()
    if len(payload) > MAX_WIRE_BYTES:
        raise ProtocolError("Wire message exceeds declared resource bound")
    return payload


def decode_message(payload):
    if len(payload) > MAX_WIRE_BYTES:
        raise ProtocolError("Wire message exceeds declared resource bound")
    with np.load(io.BytesIO(payload), allow_pickle=False) as archive:
        meta = archive["__manifest__"]
        if meta.dtype != np.uint8 or meta.ndim != 1:
            raise ProtocolError("Malformed numeric wire manifest")
        manifest = json.loads(meta.tobytes().decode())
        if manifest.get("schema") != WIRE_SCHEMA or set(manifest) != {"schema", "tree"}:
            raise ProtocolError("Unknown numeric wire schema")
        used = set()

        def decode(value):
            if isinstance(value, dict) and set(value) == {"__array__"}:
                key = value["__array__"]
                if not isinstance(key, str) or key == "__manifest__":
                    raise ProtocolError("Malformed numeric array reference")
                array = archive[key]
                if array.dtype.kind not in "biuf":
                    raise ProtocolError("Object/string arrays forbidden")
                used.add(key)
                return array.copy()
            if isinstance(value, dict) and set(value) == {"__float__"}:
                return {"nan": np.nan, "inf": np.inf, "-inf": -np.inf}[value["__float__"]]
            if isinstance(value, dict):
                return {k: decode(v) for k, v in value.items()}
            if isinstance(value, list):
                return [decode(v) for v in value]
            return value

        result = decode(manifest["tree"])
        if set(archive.files) != used | {"__manifest__"}:
            raise ProtocolError("Unreferenced wire objects are forbidden")
        return result


def numeric_content_digest(value):
    """Hash semantic wire content without ZIP timestamps/container metadata."""
    arrays = {}
    tree = _encode(value, arrays)
    manifest = {"tree": tree, "arrays": {
        key: {"dtype": array.dtype.str, "shape": list(array.shape),
              "sha256": hashlib.sha256(array.tobytes()).hexdigest()}
        for key, array in arrays.items()}}
    return hashlib.sha256(json.dumps(manifest, sort_keys=True, allow_nan=False,
                                     separators=(",", ":")).encode()).hexdigest()


def _freeze_summary(state):
    keys = ("config", "E", "centers", "scales", "adj", "channel_types", "fit_service_mask",
            "degrees", "coefficients", "intercepts", "fit_model_mask", "model_mask",
            "residual_centers", "residual_scales", "calibration_errors",
            "calibration_predictions", "fit_target_mask", "calibration_target_mask")
    summary = {key: state[key] for key in keys}
    diagnostics = {key: value for key, value in state["diagnostics"].items()
                   if key != "applicability_reasons"}
    reasons = state["diagnostics"]["applicability_reasons"]
    legend = sorted(set(reasons.ravel().tolist()))
    codes = np.zeros(reasons.shape, dtype=np.int64)
    for index, reason in enumerate(legend):
        codes[reasons == reason] = index
    diagnostics.update(applicability_reason_codes=codes, applicability_reason_legend=legend)
    summary["diagnostics"] = diagnostics
    summary["frozen_numeric_sha256"] = numeric_content_digest(summary)
    return summary


def _rank(local, adjacency, configs):
    if adjacency.ndim == 2:
        return [rank_scores(local, adjacency, **config) for config in configs]
    return [[rank_scores(local, graph, **config) for config in configs]
            for graph in adjacency]


class NumericSession:
    """One child session; C5 states are inaccessible to controller mutation."""

    def __init__(self):
        self.states = []
        self.poisoned = False
        self.next_bin = None

    def dispatch(self, message):
        validate_request(message)
        op = message["op"]
        if op == "ping":
            return {"schema": WIRE_SCHEMA,
                    "project_modules": sorted(name for name in sys.modules
                                              if name.startswith("scripts.task_e.")),
                    "isolation": "NUMERIC_API_AND_PROCESS_NOT_HOSTILE_OS_SANDBOX"}
        if op == "close":
            return {"closed": True}
        if op == "fit_c5":
            self.states, self.poisoned, self.next_bin = [], False, None
            new_states = [fit_detector(message["warmup"], message["adj"],
                                       message["channel_types"], message["fit_service_mask"], cfg)
                          for cfg in message["configs"]]
            self.states = new_states
            self.next_bin = len(message["warmup"])
            return {"next_bin_index": self.next_bin,
                    "models": [_freeze_summary(state) for state in new_states]}
        if op == "score_c5":
            if not self.states or self.poisoned:
                raise ProtocolError("No usable fitted C5 session")
            if message["bin_index"] != self.next_bin:
                raise ProtocolError("Only the next chronological bin is admitted; no skips/replays/epochs")
            if message["values"].shape != self.states[0]["E"].shape:
                raise ProtocolError("Current bin axes differ from frozen model")
            try:
                full = [score_bin(state, message["values"]) for state in self.states]
            except Exception:
                # Some earlier states may already have advanced. Never retry a
                # partial transaction and silently diverge config chronology.
                self.poisoned = True
                raise
            self.next_bin += 1
            retained = {"score", "residuals", "errors", "predictions", "target_mask",
                        "z", "endpoint", "start", "scored_channels", "tv_score",
                        "tv_channels", "tv_edge_counts", "local_magnitude", "tv_failure"}
            return {"bin_index": message["bin_index"], "results": [
                {k: v for k, v in output.items() if k in retained} for output in full]}
        if op == "c1":
            evidence = local_scores(message["ref"], message["query"],
                                    message["channel_types"], message["local_config"])
            ranks = _rank(evidence["local"], message["adj"], message["rank_configs"]) if message.get("rank_configs") else []
            return {"evidence": evidence, "rankings": ranks}
        if op == "rank":
            return {"rankings": _rank(message["local"], message["adj"], message["configs"])}
        raise ProtocolError("Unreachable operation")


def _read_exact(stream, size):
    pieces = []
    remaining = size
    while remaining:
        piece = stream.read(remaining)
        if not piece:
            raise EOFError("Incomplete numeric pipe frame")
        pieces.append(piece)
        remaining -= len(piece)
    return b"".join(pieces)


def serve():
    session = NumericSession()
    while True:
        header = sys.stdin.buffer.read(8)
        if not header:
            return
        try:
            if len(header) != 8:
                raise ProtocolError("Incomplete numeric frame header")
            size = struct.unpack("!Q", header)[0]
            if size > MAX_WIRE_BYTES:
                raise ProtocolError("Numeric frame exceeds resource bound")
            request = decode_message(_read_exact(sys.stdin.buffer, size))
            result = session.dispatch(request)
            response = {"ok": True, "result": result}
        except Exception as exc:
            response = {"ok": False, "error_type": type(exc).__name__, "error": str(exc)}
            request = None
        encoded = encode_message(response)
        sys.stdout.buffer.write(struct.pack("!Q", len(encoded)))
        sys.stdout.buffer.write(encoded)
        sys.stdout.buffer.flush()
        if request and request.get("op") == "close":
            return


if __name__ == "__main__":
    serve()
